CREATE OR REPLACE PROCEDURE sp(
    para_product_title text,
    para_product_id integer,
    para_transaction_id integer
)
LANGUAGE plpgsql
AS $$
BEGIN
    IF EXISTS (SELECT 1 FROM Invoice_Line_Items WHERE product_title = para_product_title) THEN
        UPDATE Invoice_Line_Items
           SET product_id = para_product_id * 2
         WHERE product_title = para_product_title;
    ELSE
        INSERT INTO Invoice_Line_Items (product_title, product_id)
        VALUES (para_product_title, para_product_id);
    END IF;

    DELETE FROM Financial_Transactions
     WHERE transaction_id < para_transaction_id;

    IF para_transaction_id > 0 THEN
        DELETE FROM Financial_Transactions
         WHERE transaction_amount < 0;
    END IF;

    DELETE FROM Financial_Transactions ft
     WHERE ft.invoice_number IN (
         SELECT ili.invoice_number
           FROM Invoice_Line_Items ili
          WHERE ili.product_title = para_product_title
            AND ili.invoice_number IS NOT NULL
     );
END;
$$;

